def norm(s):
 r=min(x for x,y in s);c=min(y for x,y in s);return frozenset((x-r,y-c) for x,y in s)
def transforms(s):
 ret=[]
 for flip in [False,True]:
  for k in range(4):
   z=[]
   for x,y in s:
    if flip:y=-y
    for _ in range(k): x,y=y,-x
    z.append((x,y))
   ret.append(norm(z))
 return set(ret)
def hits(s,shape):
 for sh in transforms(shape):
  h=max(x for x,y in sh);w=max(y for x,y in sh)
  for r in range(12-h):
   for c in range(12-w):
    if {(r+x,c+y) for x,y in sh}<=s:return (r,c,sh)
